import { existsSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { LOGO_SIZES, MASCOT_HEIGHTS, MASCOTS, SCENES } from "./mascots";

// the manifest is generated by `bun run mascots`; it must describe files that are really there
const web = join(__dirname, "../..");
const file = (path: string) => join(web, path);

describe("mascot manifest", () => {
  it("has every pose of every role, and Moko", () => {
    for (const role of ["knight", "seer", "judge", "bard"]) {
      for (const pose of ["idle", "cheer", "wave", "peek", "oops"]) expect(MASCOTS).toHaveProperty(`${role}-${pose}`);
    }
    for (const pose of ["hello", "love", "wow", "party"]) expect(MASCOTS).toHaveProperty(`moko-${pose}`);
  });

  it("points at files that exist", () => {
    const missing: string[] = [];
    for (const name of Object.keys(MASCOTS)) {
      for (const h of MASCOT_HEIGHTS) if (!existsSync(file(`public/mascots/${name}-${h}.webp`))) missing.push(`${name}-${h}`);
    }
    for (const [name, scene] of Object.entries(SCENES)) {
      for (const w of scene.widths) if (!existsSync(file(`public/scenes/${name}-${w}.webp`))) missing.push(`${name}-${w}`);
    }
    for (const s of LOGO_SIZES) if (!existsSync(file(`public/brand/logo-${s}.png`))) missing.push(`logo-${s}`);
    for (const icon of ["src/app/icon.png", "src/app/apple-icon.png"]) if (!existsSync(file(icon))) missing.push(icon);
    expect(missing).toEqual([]);
  });

  it("gives sizes at the largest height", () => {
    for (const size of Object.values(MASCOTS)) {
      expect(size.height).toBe(MASCOT_HEIGHTS.at(-1));
      expect(size.width).toBeGreaterThan(0);
    }
    for (const scene of Object.values(SCENES)) expect(scene.width).toBe(scene.widths.at(-1));
  });
});
